from __future__ import annotations

from dataclasses import dataclass
import re
from typing import Iterable


@dataclass(frozen=True, slots=True)
class Book:
    id: int
    name: str
    slug: str
    chapters: int
    testament: str
    aliases: tuple[str, ...]


# Canonical Russian Synodal 66-book catalogue. The API slug is deliberately local,
# making the external API surface isolated to BibleApi.
_ROWS = [
 ("Бытие","genesis",50,"ВЗ","Быт,Бытие"),("Исход","exodus",40,"ВЗ","Исх,Исход"),("Левит","leviticus",27,"ВЗ","Лев,Левит"),("Числа","numbers",36,"ВЗ","Чис,Числа"),("Второзаконие","deuteronomy",34,"ВЗ","Втор,Второзаконие"),("Иисус Навин","joshua",24,"ВЗ","Нав,Иис Навин,Иисус Навин"),("Судьи","judges",21,"ВЗ","Суд,Судьи"),("Руфь","ruth",4,"ВЗ","Руфь"),("1 Царств","1samuel",31,"ВЗ","1Цар,1 Цар,1Царств,1 Царств"),("2 Царств","2samuel",24,"ВЗ","2Цар,2 Цар,2Царств,2 Царств"),("3 Царств","1kings",22,"ВЗ","3Цар,3 Цар,3Царств,3 Царств"),("4 Царств","2kings",25,"ВЗ","4Цар,4 Цар,4Царств,4 Царств"),("1 Паралипоменон","1chronicles",29,"ВЗ","1Пар,1 Пар,1Паралипоменон"),("2 Паралипоменон","2chronicles",36,"ВЗ","2Пар,2 Пар,2Паралипоменон"),("Ездра","ezra",10,"ВЗ","Езд,Ездра"),("Неемия","nehemiah",13,"ВЗ","Неем,Неемия"),("Есфирь","esther",10,"ВЗ","Есф,Есфирь"),("Иов","job",42,"ВЗ","Иов"),("Псалтирь","psalms",150,"ВЗ","Пс,Псалтирь,Псалом"),("Притчи","proverbs",31,"ВЗ","Прит,Притчи"),("Екклесиаст","ecclesiastes",12,"ВЗ","Еккл,Екклесиаст"),("Песнь Песней","song-of-solomon",8,"ВЗ","Песн,Песнь"),("Исаия","isaiah",66,"ВЗ","Ис,Исаия"),("Иеремия","jeremiah",52,"ВЗ","Иер,Иеремия"),("Плач Иеремии","lamentations",5,"ВЗ","Плач,Плач Иеремии"),("Иезекииль","ezekiel",48,"ВЗ","Иез,Иезекииль"),("Даниил","daniel",12,"ВЗ","Дан,Даниил"),("Осия","hosea",14,"ВЗ","Ос,Осия"),("Иоиль","joel",3,"ВЗ","Иоиль"),("Амос","amos",9,"ВЗ","Амос"),("Авдий","obadiah",1,"ВЗ","Авд,Авдий"),("Иона","jonah",4,"ВЗ","Иона"),("Михей","micah",7,"ВЗ","Мих,Михей"),("Наум","nahum",3,"ВЗ","Наум"),("Аввакум","habakkuk",3,"ВЗ","Авв,Аввакум"),("Софония","zephaniah",3,"ВЗ","Соф,Софония"),("Аггей","haggai",2,"ВЗ","Агг,Аггей"),("Захария","zechariah",14,"ВЗ","Зах,Захария"),("Малахия","malachi",4,"ВЗ","Мал,Малахия"),
 ("От Матфея","matthew",28,"НЗ","Мф,Матфей,Матфея"),("От Марка","mark",16,"НЗ","Мк,Марк,Марка"),("От Луки","luke",24,"НЗ","Лк,Лука,Луки"),("От Иоанна","john",21,"НЗ","Ин,Иоан,Иоанна,Иоанн"),("Деяния","acts",28,"НЗ","Деян,Деяния"),("Римлянам","romans",16,"НЗ","Рим,Римлянам"),("1 Коринфянам","1corinthians",16,"НЗ","1Кор,1 Кор,1Коринфянам"),("2 Коринфянам","2corinthians",13,"НЗ","2Кор,2 Кор,2Коринфянам"),("Галатам","galatians",6,"НЗ","Гал,Галатам"),("Ефесянам","ephesians",6,"НЗ","Еф,Ефесянам"),("Филиппийцам","philippians",4,"НЗ","Флп,Филиппийцам"),("Колоссянам","colossians",4,"НЗ","Кол,Колоссянам"),("1 Фессалоникийцам","1thessalonians",5,"НЗ","1Фес,1 Фес,1Фессалоникийцам"),("2 Фессалоникийцам","2thessalonians",3,"НЗ","2Фес,2 Фес,2Фессалоникийцам"),("1 Тимофею","1timothy",6,"НЗ","1Тим,1 Тим,1Тимофею"),("2 Тимофею","2timothy",4,"НЗ","2Тим,2 Тим,2Тимофею"),("Титу","titus",3,"НЗ","Тит,Титу"),("Филимону","philemon",1,"НЗ","Флм,Филимону"),("Евреям","hebrews",13,"НЗ","Евр,Евреям"),("Иакова","james",5,"НЗ","Иак,Иакова"),("1 Петра","1peter",5,"НЗ","1Пет,1 Пет,1Петра"),("2 Петра","2peter",3,"НЗ","2Пет,2 Пет,2Петра"),("1 Иоанна","1john",5,"НЗ","1Ин,1 Ин,1Иоанна"),("2 Иоанна","2john",1,"НЗ","2Ин,2 Ин,2Иоанна"),("3 Иоанна","3john",1,"НЗ","3Ин,3 Ин,3Иоанна"),("Иуды","jude",1,"НЗ","Иуд,Иуды"),("Откровение","revelation",22,"НЗ","Откр,Откровение,Апокалипсис"),
]
BOOKS = tuple(Book(i + 1, name, slug, chapters, testament, tuple(a.strip() for a in aliases.split(","))) for i, (name, slug, chapters, testament, aliases) in enumerate(_ROWS))


def normalize(value: str) -> str:
    return re.sub(r"\s+", "", value.casefold().replace("ё", "е").strip())


def find_book(value: str) -> Book | None:
    needle = normalize(value)
    matches = [book for book in BOOKS if needle in {normalize(a) for a in (*book.aliases, book.name)}]
    return matches[0] if len(matches) == 1 else None


def books_by_testament(testament: str) -> Iterable[Book]:
    return (book for book in BOOKS if book.testament == testament)
